package com.papsign.ktor.openapigen

import java.util.Properties

object SwaggerUIVersion {
    private val log = classLogger()

    val version: String =
        readVersion("/META-INF/maven/org.webjars/swagger-ui/pom.properties")
            ?: run {
                log.warn("Klarte ikke hente versjon på swagger UI via avhengigheten")
                // Generated by the build from the declared org.webjars:swagger-ui version
                readVersion("swagger-ui.properties")
                    ?: error("Swagger UI version is missing: neither the WebJar metadata nor swagger-ui.properties is on the classpath")
            }

    private fun readVersion(
        resource: String,
    ): String? =
        this::class.java.getResourceAsStream(resource)?.use { stream ->
            Properties().apply { load(stream) }.getProperty("version")
        }
}
